import{_ as e,o as a,c as r,a0 as n}from"./chunks/framework.D7EjqxMK.js";const c=JSON.parse('{"title":"安全对齐与护栏","description":"","frontmatter":{},"headers":[],"relativePath":"06-agent/04_工程实践/05_安全对齐与护栏.md","filePath":"06-agent/04_工程实践/05_安全对齐与护栏.md"}'),o={name:"06-agent/04_工程实践/05_安全对齐与护栏.md"};function d(i,t,l,h,s,g){return a(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="安全对齐与护栏" tabindex="-1">安全对齐与护栏 <a class="header-anchor" href="#安全对齐与护栏" aria-label="Permalink to &quot;安全对齐与护栏&quot;">​</a></h1><blockquote><p><strong>在知识图谱中的位置</strong>：模块四 · 04_工程实践 · 第 5 节 <strong>难度</strong>：⭐⭐⭐ | <strong>前置知识</strong>：Agent 工程化</p></blockquote><hr><h2 id="_1-owasp-agentic-ai-top-10-2025-2026-已验证来源" tabindex="-1">1. OWASP Agentic AI Top 10 2025/2026（已验证来源） <a class="header-anchor" href="#_1-owasp-agentic-ai-top-10-2025-2026-已验证来源" aria-label="Permalink to &quot;1. OWASP Agentic AI Top 10 2025/2026（已验证来源）&quot;">​</a></h2><p>OWASP 发布了针对 Agentic Applications 的 Top 10 安全风险标准，2025 年 12 月更新为 v1.1。</p><p><strong>来源</strong>：<a href="https://genai.owasp.org/2025/12/09/owasp-top-10-for-agentic-applications-the-benchmark-for-agentic-security-in-the-age-of-autonomous-ai/" target="_blank" rel="noreferrer">OWASP Top 10 for Agentic Applications</a> <a href="https://genai.owasp.org/download/45674/" target="_blank" rel="noreferrer">来源: OWASP 报告</a></p><h3 id="十大风险" tabindex="-1">十大风险 <a class="header-anchor" href="#十大风险" aria-label="Permalink to &quot;十大风险&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>风险</th><th>描述</th><th>严重度</th></tr></thead><tbody><tr><td>A01</td><td>工具滥用</td><td>Agent 调用未授权工具执行破坏性操作</td><td>🔴 极高</td></tr><tr><td>A02</td><td>提示注入</td><td>恶意输入诱导 Agent 执行危险操作</td><td>🔴 极高</td></tr><tr><td>A03</td><td>越狱攻击</td><td>绕过安全限制，获取不当输出</td><td>🔴 极高</td></tr><tr><td>A04</td><td>数据泄露</td><td>Agent 暴露敏感数据（PII、密钥等）</td><td>🟠 高</td></tr><tr><td>A05</td><td>幻觉执行</td><td>基于错误信息执行操作</td><td>🟠 高</td></tr><tr><td>A06</td><td>权限逃逸</td><td>Agent 超出设计权限执行操作</td><td>🟠 高</td></tr><tr><td>A07</td><td>无限循环/资源耗尽</td><td>Agent 陷入死循环消耗资源</td><td>🟡 中</td></tr><tr><td>A08</td><td>供应链攻击</td><td>通过工具/依赖注入恶意代码</td><td>🟠 高</td></tr><tr><td>A09</td><td>审计缺失</td><td>Agent 行为不可追溯</td><td>🟡 中</td></tr><tr><td>A10</td><td>伦理与偏见</td><td>Agent 做出歧视性或不当决策</td><td>🟡 中</td></tr></tbody></table><hr><h2 id="_2-openagentsafety-已验证来源" tabindex="-1">2. OpenAgentSafety（已验证来源） <a class="header-anchor" href="#_2-openagentsafety-已验证来源" aria-label="Permalink to &quot;2. OpenAgentSafety（已验证来源）&quot;">​</a></h2><p><strong>来源</strong>：<a href="https://openreview.net/pdf?id=xggSxCFQbA" target="_blank" rel="noreferrer">OpenAgentSafety (ICLR 2026)</a></p><p>由 Carnegie Mellon University、Meta AI、Carnegie Mellon 等机构联合提出。OpenAgentSafety 是一个全面评估真实世界 AI Agent 安全性的框架。</p><hr><h2 id="_3-安全护栏实现" tabindex="-1">3. 安全护栏实现 <a class="header-anchor" href="#_3-安全护栏实现" aria-label="Permalink to &quot;3. 安全护栏实现&quot;">​</a></h2><h3 id="输入护栏" tabindex="-1">输入护栏 <a class="header-anchor" href="#输入护栏" aria-label="Permalink to &quot;输入护栏&quot;">​</a></h3><ul><li>检测越狱尝试</li><li>过滤敏感信息（PII）</li></ul><h3 id="输出护栏" tabindex="-1">输出护栏 <a class="header-anchor" href="#输出护栏" aria-label="Permalink to &quot;输出护栏&quot;">​</a></h3><ul><li>过滤敏感信息</li><li>检查是否有不安全建议</li></ul><h3 id="工具护栏" tabindex="-1">工具护栏 <a class="header-anchor" href="#工具护栏" aria-label="Permalink to &quot;工具护栏&quot;">​</a></h3><ul><li>分级权限（read / write / sensitive / critical）</li><li>高危操作必须人工审批</li></ul><hr><h2 id="_4-参考资料" tabindex="-1">4. 参考资料 <a class="header-anchor" href="#_4-参考资料" aria-label="Permalink to &quot;4. 参考资料&quot;">​</a></h2><ul><li><a href="https://genai.owasp.org/2025/12/09/owasp-top-10-for-agentic-applications-the-benchmark-for-agentic-security-in-the-age-of-autonomous-ai/" target="_blank" rel="noreferrer">OWASP Top 10 for Agentic Applications</a></li><li><a href="https://genai.owasp.org/download/50592/" target="_blank" rel="noreferrer">State of Agentic AI Security and Governance (OWASP)</a></li><li><a href="https://genai.owasp.org/download/45674/" target="_blank" rel="noreferrer">Agentic AI Threats and Mitigations (OWASP v1.1, Dec 2025)</a></li><li><a href="https://openreview.net/pdf?id=xggSxCFQbA" target="_blank" rel="noreferrer">OpenAgentSafety (ICLR 2026)</a></li><li><a href="https://huggingface.co/blog/royswastik/evaluating-agentic-ai-part-4-security" target="_blank" rel="noreferrer">Part 4: Security Evaluation of Agentic AI Systems (Hugging Face)</a></li></ul>',23)])])}const A=e(o,[["render",d]]);export{c as __pageData,A as default};
